{
  "name": "多比特量子控制与读出系统",
  "name_en": "Multi-qubit Quantum Control and Readout System",
  "manufacturer": "",
  "description": "用于超导量子比特实验的组合式电子测控系统，协同任意波形发生器、数字时序控制器、通量控制链路和积分采集读出设备，对多个量子比特进行时序对齐、通量脉冲控制与读出测量。常用于时域实验、单次读出、相关性测量和系统标定。",
  "description_en": "A composite electronic control and measurement system for superconducting qubit experiments. It coordinates waveform generators, digital timing controllers, flux-control lines, and integrated readout hardware to align timing, apply flux pulses, and perform qubit readout across multiple qubits. It is commonly used for time-domain experiments, single-shot readout, correlation measurements, and calibration.",
  "tag_hints": [
    "superconducting qubits",
    "quantum control electronics",
    "qubit readout",
    "flux pulse control",
    "timing synchronization",
    "time-domain experiments",
    "single-shot readout"
  ],
  "actions": [
    {
      "action_name": "auto-prepare_timing",
      "description": "配置控制与读出通道的延迟和触发时序，使多台量子测控设备精确对齐。",
      "description_en": "Configure delays and trigger timing for control and readout channels so multiple quantum-control instruments are precisely aligned."
    },
    {
      "action_name": "auto-prepare_fluxing",
      "description": "为指定量子比特配置通量控制链路和相关脉冲设置。",
      "description_en": "Configure the flux-control path and related pulse settings for the specified qubits."
    },
    {
      "action_name": "auto-prepare_readout",
      "description": "为指定量子比特配置读出链路、采集通道和积分测量设置。",
      "description_en": "Configure the readout path, acquisition channels, and integration settings for the specified qubits."
    },
    {
      "action_name": "auto-prepare_for_timedomain",
      "description": "为时域实验联合准备量子比特控制、通量和读出测量配置。",
      "description_en": "Prepare the combined qubit-control, flux, and readout configuration for a time-domain experiment."
    },
    {
      "action_name": "auto-prepare_for_inspire",
      "description": "为特定量子实验流程准备读出与采集设置，适用于单次读出等测量。",
      "description_en": "Prepare readout and acquisition settings for a specific quantum-experiment workflow, including single-shot style measurements."
    },
    {
      "action_name": "auto-hal_get_flux_amp_parameter",
      "description": "获取指定量子比特的通量脉冲幅度参数。",
      "description_en": "Get the flux-pulse amplitude parameter for the specified qubit."
    },
    {
      "action_name": "auto-get_correlation_detector",
      "description": "获取用于多量子比特相关性读出测量的采集配置。",
      "description_en": "Get the acquisition configuration for correlation-based readout measurements across multiple qubits."
    },
    {
      "action_name": "auto-get_int_logging_detector",
      "description": "获取用于记录积分读出结果的采集配置。",
      "description_en": "Get the acquisition configuration for logging integrated readout results."
    },
    {
      "action_name": "auto-get_input_avg_det",
      "description": "获取用于输入信号平均测量的采集配置。",
      "description_en": "Get the acquisition configuration for averaged input-signal measurements."
    },
    {
      "action_name": "auto-get_int_avg_det",
      "description": "获取用于积分平均读出的采集配置。",
      "description_en": "Get the acquisition configuration for averaged integrated readout measurements."
    }
  ]
}

